// ─────────────────────────────────────────────────────────────────────────────
// Global app state (zustand). Authored by scaffolding so parallel agents share a
// stable shape. Agents READ state and CALL setters — they do not edit this file.
//   • The player module drives: status, currentSentence, error.
//   • The UI reads everything and calls setters for user-driven changes
//     (voiceId, rate, theme, fileName).
// Persisted to localStorage: theme, voiceId, rate, skipSkippable, autoScroll.
// ─────────────────────────────────────────────────────────────────────────────
import { create } from 'zustand'
import type { Doc, EngineState, PlayerStatus, Theme, Toast, Voice } from './types'

const LS_KEY = 'aloud.prefs.v1'

interface PersistedPrefs {
  theme: Theme
  voiceId: string
  rate: number
  /** Skip bracketed/parenthetical content when reading aloud. */
  skipSkippable: boolean
  /** Auto-scroll the active sentence into view while playing. */
  autoScroll: boolean
}

function systemTheme(): Theme {
  if (typeof window !== 'undefined' && window.matchMedia) {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
  }
  return 'light'
}

function loadPrefs(): PersistedPrefs {
  const fallback: PersistedPrefs = {
    theme: systemTheme(),
    voiceId: 'af_heart',
    rate: 1,
    skipSkippable: true,
    autoScroll: true,
  }
  try {
    const raw = localStorage.getItem(LS_KEY)
    if (!raw) return fallback
    return { ...fallback, ...JSON.parse(raw) }
  } catch {
    return fallback
  }
}

function savePrefs(p: PersistedPrefs) {
  try {
    localStorage.setItem(LS_KEY, JSON.stringify(p))
  } catch {
    /* ignore quota / privacy-mode errors */
  }
}

export interface AppState {
  // ── connection ──
  /**
   * Engine liveness. Replaces the old `backendOnline` boolean so the UI can tell
   * "starting up" apart from "not there" — the review's P0-1 complaint was as
   * much about the false "is the backend running?" message as about the failure.
   */
  engineState: EngineState
  setEngineState: (s: EngineState) => void

  // ── voices ──
  voices: Voice[]
  setVoices: (v: Voice[]) => void
  voiceId: string
  setVoiceId: (id: string) => void

  // ── playback prefs ──
  rate: number
  setRate: (r: number) => void
  /** Skip bracketed/parenthetical content when reading aloud (persisted). */
  skipSkippable: boolean
  setSkipSkippable: (v: boolean) => void
  /** Auto-scroll the active sentence into view while playing (persisted). */
  autoScroll: boolean
  setAutoScroll: (v: boolean) => void

  // ── theme ──
  theme: Theme
  setTheme: (t: Theme) => void
  toggleTheme: () => void

  // ── document ──
  doc: Doc | null
  setDoc: (d: Doc | null) => void
  fileName: string | null
  setFileName: (n: string | null) => void
  loadProgress: number // 0..1 while parsing a PDF
  setLoadProgress: (n: number) => void

  // ── player runtime (driven by the player module) ──
  status: PlayerStatus
  setStatus: (s: PlayerStatus) => void
  currentSentence: number // index into doc.sentences, -1 if none
  setCurrentSentence: (i: number) => void
  currentWord: number // index into the CURRENT sentence's word tokens, -1 if none
  setCurrentWord: (i: number) => void

  // ── buffering (driven by the player's scheduler) ──
  /**
   * Seconds of source audio already synthesized ahead of the playhead. Drives the
   * secondary fill on the scrub bar (F2.7). Source seconds, not listening
   * seconds — at 2x this depletes twice as fast.
   */
  bufferAheadSeconds: number
  setBufferAheadSeconds: (s: number) => void

  // ── skipped sentences ──
  /**
   * Sentences that failed synthesis after every retry. Playback steps over them
   * rather than stopping (F1.5); the reader marks them inline. Cleared on load.
   */
  skippedSentences: number[]
  markSkipped: (id: number) => void

  // ── messaging ──
  /**
   * PERSISTENT banner. Reserved for states needing user action — realistically
   * only "the engine is unreachable". A single sentence failing must never set
   * this. Cleared automatically on the next successful synthesis (F4.1, F4.4).
   */
  error: string | null
  setError: (e: string | null) => void
  /** TRANSIENT message for recoverable problems (F4.3). */
  toast: Toast | null
  pushToast: (text: string) => void
  dismissToast: () => void

  reset: () => void
}

const initialPrefs = loadPrefs()

export const useStore = create<AppState>((set, get) => {
  // Persist the current persisted-pref slice. Call AFTER set() so it snapshots
  // the freshest values; keeps every setter in sync as new prefs are added.
  const persist = () => {
    const s = get()
    savePrefs({
      theme: s.theme,
      voiceId: s.voiceId,
      rate: s.rate,
      skipSkippable: s.skipSkippable,
      autoScroll: s.autoScroll,
    })
  }

  return {
  engineState: 'unknown',
  setEngineState: (s) => set({ engineState: s }),

  voices: [],
  setVoices: (v) => set({ voices: v }),
  voiceId: initialPrefs.voiceId,
  setVoiceId: (id) => {
    set({ voiceId: id })
    persist()
  },

  rate: initialPrefs.rate,
  setRate: (r) => {
    const rate = Math.min(3, Math.max(0.5, r))
    set({ rate })
    persist()
  },

  skipSkippable: initialPrefs.skipSkippable,
  setSkipSkippable: (v) => {
    set({ skipSkippable: v })
    persist()
  },

  autoScroll: initialPrefs.autoScroll,
  setAutoScroll: (v) => {
    set({ autoScroll: v })
    persist()
  },

  theme: initialPrefs.theme,
  setTheme: (t) => {
    set({ theme: t })
    persist()
  },
  toggleTheme: () => {
    const t = get().theme === 'dark' ? 'light' : 'dark'
    set({ theme: t })
    persist()
  },

  doc: null,
  setDoc: (d) => set({ doc: d }),
  fileName: null,
  setFileName: (n) => set({ fileName: n }),
  loadProgress: 0,
  setLoadProgress: (n) => set({ loadProgress: n }),

  status: 'idle',
  setStatus: (s) => set({ status: s }),
  currentSentence: -1,
  // Changing the active sentence always clears the word highlight, so a stale
  // word from the previous sentence can never linger on the new one.
  setCurrentSentence: (i) =>
    set((s) => (s.currentSentence === i ? {} : { currentSentence: i, currentWord: -1 })),
  currentWord: -1,
  setCurrentWord: (i) => set({ currentWord: i }),

  bufferAheadSeconds: 0,
  setBufferAheadSeconds: (s) => set({ bufferAheadSeconds: Math.max(0, s) }),

  skippedSentences: [],
  markSkipped: (id) =>
    set((s) => (s.skippedSentences.includes(id) ? {} : { skippedSentences: [...s.skippedSentences, id] })),

  error: null,
  setError: (e) => set({ error: e }),

  toast: null,
  // The id makes a repeated message re-fire; the text alone would look unchanged
  // to React and the toast would never re-appear.
  pushToast: (text) => set((s) => ({ toast: { id: (s.toast?.id ?? 0) + 1, text } })),
  dismissToast: () => set({ toast: null }),

  reset: () =>
    set({
      doc: null,
      fileName: null,
      loadProgress: 0,
      status: 'idle',
      currentSentence: -1,
      currentWord: -1,
      bufferAheadSeconds: 0,
      skippedSentences: [],
      error: null,
      toast: null,
    }),
  }
})
